import{emptySessionView,foldReceivedEvent}from"#protocol/session-projection/fold.js";import{openSignIns}from"#protocol/session-projection/reader.js";import{signInOf}from"#channel/sign-in.js";async function findPendingAuthorization(e,t){let n=emptySessionView();for await(let t of e.stream({follow:!1,startIndex:-500}))foldReceivedEvent(n,t);return openSignIns(n).map(e=>signInOf(n,e.interactionId)).findLast(t)}export{findPendingAuthorization};